// -----------------------------------------------------------------------------
// Helper classes & functions
// -----------------------------------------------------------------------------

class TaskResult
{
    public string $name;
    public string $status = 'OK'; // OK, WARNING, ERROR
    /** @var string[] */
    public array $messages = [];
    /** @var string[] */
    public array $warnings = [];
    /** @var string[] */
    public array $errors = [];
    public float $startTime;
    public float $endTime;

    public function __construct(string $name)
    {
        $this->name = $name;
        $this->startTime = microtime(true);
        $this->endTime = $this->startTime;
    }

    public function finish(): void
    {
        $this->endTime = microtime(true);
    }

    public function addMessage(string $msg): void
    {
        $this->messages[] = $msg;
    }

    public function addWarning(string $msg): void
    {
        $this->warnings[] = $msg;
        if ($this->status === 'OK') {
            $this->status = 'WARNING';
        }
    }

    public function addError(string $msg): void
    {
        $this->errors[] = $msg;
        $this->status = 'ERROR';
    }

    public function durationSeconds(): float
    {
        return $this->endTime - $this->startTime;
    }
}

function ensureDir(string $path): void
{
    if (!is_dir($path)) {
        if (!mkdir($path, 0775, true) && !is_dir($path)) {
            throw new RuntimeException("Unable to create directory: $path");
        }
    }
}

function logLine(array $config, string $line): void
{
    if (empty($config['logFile'])) {
        return;
    }
    $ts = date('Y-m-d H:i:s');
    @file_put_contents($config['logFile'], "[$ts] $line\n", FILE_APPEND);
}

/**
 * Get PDO connection to MySQL.
 */
function getPdo(array $config, string $dbName = 'information_schema'): PDO
{
    $dsn = sprintf(
        'mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',
        $config['mysql']['host'],
        $config['mysql']['port'],
        $dbName
    );

    $pdo = new PDO($dsn, $config['mysql']['user'], $config['mysql']['pass'], [
        PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
    ]);

    return $pdo;
}

/**
 * Return list of Heurist DB names (schema_name like 'hdb_%').
 */
function getHeuristDatabases(array $config): array
{
    $pdo = getPdo($config, 'information_schema');
    $stmt = $pdo->query(
        "SELECT schema_name 
           FROM information_schema.schemata 
          WHERE schema_name LIKE 'hdb\_%'
          ORDER BY schema_name"
    );
    $dbs = [];
    while ($row = $stmt->fetch()) {
        $dbs[] = $row['schema_name'];
    }
    return $dbs;
}

/**
 * Execute a shell command safely, capturing stdout/stderr and exit code.
 */
function runShellCommand(string $cmd, TaskResult $res, ?string $cwd = null): int
{
    $descriptorSpec = [
        1 => ['pipe', 'w'], // stdout
        2 => ['pipe', 'w'], // stderr
    ];

    $process = proc_open($cmd, $descriptorSpec, $pipes, $cwd ?: null);

    if (!is_resource($process)) {
        $res->addError("Failed to start command: $cmd");
        return 1;
    }

    $stdout = stream_get_contents($pipes[1]);
    fclose($pipes[1]);

    $stderr = stream_get_contents($pipes[2]);
    fclose($pipes[2]);

    $exitCode = proc_close($process);

    if ($stdout !== '') {
        $res->addMessage("Command stdout for '$cmd':\n$stdout");
    }
    if ($stderr !== '') {
        $res->addWarning("Command stderr for '$cmd':\n$stderr");
    }
    if ($exitCode !== 0) {
        $res->addError("Command exited with code $exitCode: $cmd");
    }

    return $exitCode;
}

/**
 * Write TSV file from rows (array of array of scalar values).
 */
function writeTsv(string $path, array $header, array $rows): void
{
    $fh = fopen($path, 'w');
    if (!$fh) {
        throw new RuntimeException("Cannot open $path for writing");
    }
    if ($header) {
        fputcsv($fh, $header, "\t");
    }
    foreach ($rows as $row) {
        fputcsv($fh, $row, "\t");
    }
    fclose($fh);
}

// -----------------------------------------------------------------------------
// 1. BACKUPS
// -----------------------------------------------------------------------------

function task_backupAllDatabases(array $config): TaskResult
{
    $res = new TaskResult('backup_all_dbs');

    $backupDir = $config['backupDir'];
    $minSize   = (int)$config['minBackupSize'];

    try {
        ensureDir($backupDir);
    } catch (Throwable $e) {
        $res->addError("Cannot ensure backup directory $backupDir: " . $e->getMessage());
        $res->finish();
        return $res;
    }

    // Clear previous backups.
    foreach (glob($backupDir . '/*.sql') ?: [] as $file) {
        @unlink($file);
    }
    foreach (glob($backupDir . '/*.sql.bz2') ?: [] as $file) {
        @unlink($file);
    }

    $cnt      = 0;
    $success  = 0;
    $failure  = 0;
    $empty    = 0;
    $totSize  = 0;

    $dbs = getHeuristDatabases($config);
    $res->addMessage("Found " . count($dbs) . " Heurist databases to back up.");

    foreach ($dbs as $dbName) {
        $cnt++;
        $res->addMessage("$dbName : backing up ...");

        $sqlFile = $backupDir . '/' . $dbName . '.sql';
        $bz2File = $sqlFile . '.bz2';

        // mysqldump command     --databases vs --no-create-db 
        $cmd = sprintf(
'mysqldump -h%s -P%d -u%s -p%s --single-transaction --skip-triggers --skip-routines --add-drop-table --quick --skip-dump-date %s > %s',
            escapeshellarg($config['mysql']['host']),
            (int)$config['mysql']['port'],
            escapeshellarg($config['mysql']['user']),
            escapeshellarg($config['mysql']['pass']),
            escapeshellarg($dbName),
            escapeshellarg($sqlFile)
        );
        
        

        $exitDump = runShellCommand($cmd, $res, $backupDir);
        if ($exitDump !== 0) {
            $failure++;
            $res->addError("$dbName : mysqldump failed with exit code $exitDump");
            continue;
        }

        $filesize = is_file($sqlFile) ? filesize($sqlFile) : 0;

        if ($filesize <= $minSize) {
            $empty++;
            $failure++;
            $res->addWarning("$dbName : dump filesize $filesize bytes <= min $minSize – EMPTY/FAILURE; deleting.");
            @unlink($sqlFile);
            continue;
        }

        // Compress with bzip2
        $cmdBzip = sprintf('bzip2 %s', escapeshellarg($sqlFile));
        $exitBzip = runShellCommand($cmdBzip, $res, $backupDir);

        if ($exitBzip !== 0) {
            $failure++;
            $res->addError("$dbName : bzip2 failed for $sqlFile");
            @unlink($sqlFile);
            continue;
        }

        if (!is_file($bz2File)) {
            $failure++;
            $res->addError("$dbName : expected compressed file not found: $bz2File");
            continue;
        }

        $bzSize = filesize($bz2File) ?: 0;
        $totSize += $bzSize;
        $success++;
        $res->addMessage("$dbName : backup success – compressed size $bzSize bytes.");
    }

    $res->addMessage(sprintf(
        'Backup completed %s. Databases: %d. Archived successfully: %d (total size %d). Empty: %d. Failures: %d.',
        date('Y-m-d H:i:s'),
        $cnt,
        $success,
        $totSize,
        $empty,
        $failure
    ));

    if ($failure > 0 || $empty > 0) {
        $res->addWarning("Some backups failed or were empty (see details above).");
    }

    $res->finish();
    return $res;
}

function task_archiveBzipDbs(array $config): TaskResult
{
    $res = new TaskResult('archive_bzip_dbs');

    $backupDir  = $config['backupDir'];
    $archiveDir = $config['backupArchiveDir'];
    $minSize    = (int)$config['minBzipSize'];

    try {
        ensureDir($backupDir);
        ensureDir($archiveDir);
    } catch (Throwable $e) {
        $res->addError("Cannot ensure backup/archive directories: " . $e->getMessage());
        $res->finish();
        return $res;
    }

    // Remove tiny files.
    foreach (glob($archiveDir . '/hdb_*.sql.bz2*') ?: [] as $file) {
        if (filesize($file) < $minSize) {
            @unlink($file);
        }
    }
    foreach (glob($backupDir . '/hdb_*.sql.bz2') ?: [] as $file) {
        if (filesize($file) < $minSize) {
            @unlink($file);
        }
    }

    $nowDate = date('Y-m-d');
    $countNew = 0;
    $countChanged = 0;

    foreach (glob($backupDir . '/hdb_*.sql.bz2') ?: [] as $file) {
        $base = basename($file);
        $archiveFile = $archiveDir . '/' . $base;

        if (!file_exists($archiveFile)) {
            if (!copy($file, $archiveFile)) {
                $res->addError("Failed to copy new backup $file to $archiveFile");
            } else {
                $countNew++;
                $res->addMessage("File is new: $base");
            }
            continue;
        }

        $same = (filesize($file) === filesize($archiveFile));
        if ($same) {
            $same = (sha1_file($file) === sha1_file($archiveFile));
        }

        if ($same) {
            continue;
        }

        $dated = $archiveDir . '/' . $base . '.' . $nowDate;
        @rename($archiveFile, $dated);
        if (!copy($file, $archiveFile)) {
            $res->addError("Failed to archive changed backup $file -> $archiveFile");
        } else {
            $countChanged++;
            $res->addMessage("File changed – archived previous $base to $dated");
        }
    }

    $res->addMessage("Archive step completed: new={$countNew}, changed={$countChanged}");
    $res->finish();
    return $res;
}

function task_purgeArchive(array $config): TaskResult
{
    $res = new TaskResult('purge_ARCHIVE');

    $archiveDir = $config['backupArchiveDir'];
    try {
        ensureDir($archiveDir);
    } catch (Throwable $e) {
        $res->addError("Cannot ensure archive directory $archiveDir: " . $e->getMessage());
        $res->finish();
        return $res;
    }

    $files = glob($archiveDir . '/hdb_*.sql.bz2*') ?: [];
    if (!$files) {
        $res->addMessage("No hdb_*.sql.bz2 files found in $archiveDir.");
        $res->finish();
        return $res;
    }

    $now = time();
    $keep = []; // file path => true
    $latestPerMonth = []; // [dbBase][YYYY-MM] => [file, mtime]

    foreach ($files as $file) {
        $mtime = @filemtime($file);
        if (!$mtime) {
            continue;
        }
        if ($now - $mtime <= 10 * 24 * 3600) {
            $keep[$file] = true;
        }

        $baseName = basename($file);
        $pos = strpos($baseName, '.sql.bz2');
        if ($pos === false) {
            $keep[$file] = true;
            continue;
        }
        $dbBase = substr($baseName, 0, $pos);
        $ym = date('Y-m', $mtime);

        if (!isset($latestPerMonth[$dbBase][$ym]) || $mtime > $latestPerMonth[$dbBase][$ym]['mtime']) {
            $latestPerMonth[$dbBase][$ym] = ['file' => $file, 'mtime' => $mtime];
        }
    }

    foreach ($latestPerMonth as $dbBase => $months) {
        foreach ($months as $info) {
            $keep[$info['file']] = true;
        }
    }

    $deleted = 0;
    foreach ($files as $file) {
        if (isset($keep[$file])) {
            continue;
        }
        $mtime = @filemtime($file);
        if ($mtime && ($now - $mtime > 10 * 24 * 3600)) {
            if (@unlink($file)) {
                $deleted++;
                $res->addMessage("Deleting old archive file: $file");
            }
        }
    }

    $res->addMessage("Purge completed in $archiveDir – deleted $deleted file(s).");
    $res->finish();
    return $res;
}

// -----------------------------------------------------------------------------
// 2. VERIFICATIONS
// -----------------------------------------------------------------------------

function task_checkRequiredTables(array $config): TaskResult
{
    $res = new TaskResult('check_for_required_tables');

    $requiredTables = [
        'sysIdentification',
        'sysUGrps',
        'Records',
        'defRecTypes',
        'defRecStructure',
        'defDetailTypes',
        'defTerms',
        'defLanguages',
        'defCalcFunctions',
    ];

    $dbs = getHeuristDatabases($config);
    $rows = [];
    $pdoInfo = getPdo($config, 'information_schema');

    foreach ($dbs as $db) {
        try {
            $placeholders = implode(',', array_fill(0, count($requiredTables), '?'));
            $sql = "SELECT table_name 
                      FROM information_schema.tables 
                     WHERE table_schema = ? 
                       AND table_name IN ($placeholders)";
            $params = array_merge([$db], $requiredTables);
            $stmt = $pdoInfo->prepare($sql);
            $stmt->execute($params);
            $present = [];
            while ($row = $stmt->fetch()) {
                $present[] = $row['table_name'];
            }
            $missing = array_values(array_diff($requiredTables, $present));

            if ($missing) {
                $res->addWarning("$db missing tables: " . implode(', ', $missing));
                $rows[] = [$db, 'MISSING', implode(',', $missing)];
            } else {
                $rows[] = [$db, 'OK', ''];
            }
        } catch (Throwable $e) {
            $res->addError("Error checking tables in $db: " . $e->getMessage());
            $rows[] = [$db, 'ERROR', $e->getMessage()];
        }
    }

    $resultsDir = $config['resultsDir'];
    try {
        ensureDir($resultsDir);
        $path = $resultsDir . '/required_tables_check.tsv';
        writeTsv($path, ['database', 'status', 'missing_tables'], $rows);
        $res->addMessage("Wrote required-tables report to $path");
    } catch (Throwable $e) {
        $res->addError("Failed to write required tables TSV: " . $e->getMessage());
    }

    $res->finish();
    return $res;
}

