function task_listAllDbs(array $config): TaskResult
{
    $res = new TaskResult('list_all_dbs');

    $resultsDir = $config['resultsDir'];
    try {
        ensureDir($resultsDir);
    } catch (Throwable $e) {
        $res->addError("Cannot ensure results directory: " . $e->getMessage());
        $res->finish();
        return $res;
    }
    $outPath = $resultsDir . '/list_of_dbs.tsv';

    $dbs = getHeuristDatabases($config);
    $rows = [];

    foreach ($dbs as $db) {
        try {
            $pdo = getPdo($config, $db);

            $p = preg_replace('/^hdb_/', '', $db);
            $deleteCmd = "/srv/scripts/delete_database_to_archive.sh $p";

            $sql = "
                SELECT
                    :dbname AS db_name,
                    u.ugr_eMail      AS admin_email,
                    u.ugr_LastName   AS admin_last,
                    u.ugr_FirstName  AS admin_first,
                    COUNT(r.rec_ID)  AS record_count,
                    MAX(r.rec_Modified) AS last_modified,
                    YEAR(MAX(r.rec_Modified)) AS last_modified_year,
                    MONTH(MAX(r.rec_Modified)) AS last_modified_month,
                    :delete_cmd AS delete_command,
                    s.sys_dbRegisteredID,
                    s.sys_dbVersion,
                    s.sys_dbSubVersion
                FROM sysIdentification s
                JOIN sysUGrps u
                JOIN Records r
                WHERE u.ugr_ID = 2
            ";
            $stmt = $pdo->prepare($sql);
            $stmt->execute([
                ':dbname'     => $db,
                ':delete_cmd' => $deleteCmd,
            ]);
            $row = $stmt->fetch();

            if ($row) {
                $rows[] = [
                    $row['db_name'],
                    $row['admin_email'],
                    $row['admin_last'],
                    $row['admin_first'],
                    $row['record_count'],
                    $row['last_modified'],
                    $row['last_modified_year'],
                    $row['last_modified_month'],
                    $row['delete_command'],
                    $row['sys_dbRegisteredID'],
                    $row['sys_dbVersion'],
                    $row['sys_dbSubVersion'],
                ];
            } else {
                $res->addWarning("No summary row returned for $db (sysIdentification/sysUGrps/Records may be empty)");
            }
        } catch (Throwable $e) {
            $res->addError("Error listing db $db: " . $e->getMessage());
        }
    }

    usort($rows, static function ($a, $b) {
        return strcmp((string)$a[0], (string)$b[0]);
    });

    try {
        writeTsv($outPath, [
            'db_name', 'admin_email', 'admin_last', 'admin_first',
            'record_count', 'last_modified', 'last_modified_year', 'last_modified_month',
            'delete_command', 'sys_dbRegisteredID', 'sys_dbVersion', 'sys_dbSubVersion',
        ], $rows);
        $res->addMessage("Wrote DB list to $outPath");
    } catch (Throwable $e) {
        $res->addError("Failed to write DB list TSV: " . $e->getMessage());
    }

    $res->finish();
    return $res;
}

function task_listFilestoreSizes(array $config): TaskResult
{
    $res = new TaskResult('list_filestore_sizes');

    $resultsDir = $config['resultsDir'];
    try {
        ensureDir($resultsDir);
    } catch (Throwable $e) {
        $res->addError("Cannot ensure results directory: " . $e->getMessage());
        $res->finish();
        return $res;
    }

    $outPath = $resultsDir . '/filestore_sizes.txt';

    $filestoreDir = $config['filestoreDir'];

    $cmd = sprintf(
        'du -s %s/* 2>/dev/null | sort -rn > %s',
        escapeshellarg($filestoreDir),
        escapeshellarg($outPath)
    );
    $exit = runShellCommand($cmd, $res);
    if ($exit === 0) {
        $res->addMessage("Wrote filestore sizes to $outPath");
    }

    $res->finish();
    return $res;
}

function task_listAllWebsites(array $config): TaskResult
{
    $res = new TaskResult('list_all_websites');

    $resultsDir = $config['resultsDir'];
    try {
        ensureDir($resultsDir);
    } catch (Throwable $e) {
        $res->addError("Cannot ensure results directory: " . $e->getMessage());
        $res->finish();
        return $res;
    }

    $tsvPath  = $resultsDir . '/list_of_websites_on_all_dbs.tsv';
    $htmlPath = $config['webRootDir'] . '/list_of_websites_on_all_dbs.html';

    $dbs = getHeuristDatabases($config);
    $rowsHtmlLines = [];

    foreach ($dbs as $db) {
        try {
            $pdo = getPdo($config, $db);

            $sql = "
                SELECT r.rec_ID, r.rec_Title
                  FROM Records r
                 WHERE r.rec_RecTypeID IN (
                        SELECT rt.rty_ID
                          FROM defRecTypes rt
                         WHERE rt.rty_OriginatingDBID = 99
                           AND rt.rty_IDInOriginatingDB = 51
                 )
                   AND NOT r.rec_FlagTemporary
                   AND r.rec_Title NOT LIKE '%Enter a website name here%'
                   AND r.rec_Title NOT LIKE '%UNCONFIGURED SITE TITLE%'
            ";
            $stmt = $pdo->query($sql);
            while ($row = $stmt->fetch()) {
                $recId = (int)$row['rec_ID'];
                $title = (string)$row['rec_Title'];
                $server = $config['serverName'];
                $dbNameEsc = htmlspecialchars($db, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
                $titleEsc  = htmlspecialchars($title, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
                $link = sprintf(
                    '<h3><a href="https://%s/heurist/?db=%s&website&id=%d" target="_blank">%s</a></h3>',
                    $server,
                    $dbNameEsc,
                    $recId,
                    $dbNameEsc
                );
                $desc = sprintf(
                    '<pre style="font-size: 10px;margin-left:30px;">%s</pre>',
                    $titleEsc
                );
                $rowsHtmlLines[] = $link . "\n" . $desc;
            }
        } catch (Throwable $e) {
            $res->addError("Error listing websites in $db: " . $e->getMessage());
        }
    }

    sort($rowsHtmlLines, SORT_STRING);

    $rowsTsv = [];
    foreach ($rowsHtmlLines as $line) {
        $rowsTsv[] = [$line];
    }

    try {
        writeTsv($tsvPath, [], $rowsTsv);
        $res->addMessage("Wrote websites TSV (HTML snippets) to $tsvPath");
    } catch (Throwable $e) {
        $res->addError("Failed to write websites TSV: " . $e->getMessage());
    }

    try {
        ensureDir(dirname($htmlPath));
        $html = "<html><body>\n";
        $html .= sprintf(
            "<h1>Heurist websites on %s at %s</h1>\n",
            htmlspecialchars($config['serverName'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'),
            date('Y-m-d H:i:s')
        );
        foreach ($rowsHtmlLines as $block) {
            $html .= $block . "\n";
        }
        $html .= "</body></html>\n";
        file_put_contents($htmlPath, $html);
        $res->addMessage("Wrote websites HTML page to $htmlPath");
    } catch (Throwable $e) {
        $res->addError("Failed to write websites HTML page: " . $e->getMessage());
    }

    $res->finish();
    return $res;
}

function task_listAllRectypes(array $config): TaskResult
{
    $res = new TaskResult('list_all_rectypes');

    $resultsDir = $config['resultsDir'];
    try {
        ensureDir($resultsDir);
    } catch (Throwable $e) {
        $res->addError("Cannot ensure results directory: " . $e->getMessage());
        $res->finish();
        return $res;
    }

    $outPath = $resultsDir . '/list_of_rectypes_on_all_dbs.tsv';

    $dbs = getHeuristDatabases($config);
    $rectypes = [];

    foreach ($dbs as $db) {
        try {
            $pdo = getPdo($config, $db);
            $stmt = $pdo->query("SELECT rty_Name FROM defRecTypes WHERE 1");
            while ($row = $stmt->fetch()) {
                $rectypes[$row['rty_Name']] = true;
            }
        } catch (Throwable $e) {
            $res->addError("Error listing rectypes in $db: " . $e->getMessage());
        }
    }

    $names = array_keys($rectypes);
    sort($names, SORT_STRING);
    $rows = [];
    foreach ($names as $name) {
        $rows[] = [$name];
    }

    try {
        writeTsv($outPath, [], $rows);
        $res->addMessage("Wrote rectypes list to $outPath");
    } catch (Throwable $e) {
        $res->addError("Failed to write rectypes TSV: " . $e->getMessage());
    }

    $res->finish();
    return $res;
}

function task_listAllRectypesWithConceptIds(array $config): TaskResult
{
    $res = new TaskResult('list_all_rectypes_with_concept_IDs');

    $resultsDir = $config['resultsDir'];
    try {
        ensureDir($resultsDir);
    } catch (Throwable $e) {
        $res->addError("Cannot ensure results directory: " . $e->Message());
        $res->finish();
        return $res;
    }

    $outPath = $resultsDir . '/list_of_rectypes_on_all_dbs_with_concept_IDs.tsv';

    $dbs = getHeuristDatabases($config);
    $seen = [];
    $rows = [];

    foreach ($dbs as $db) {
        try {
            $pdo = getPdo($config, $db);
            $stmt = $pdo->query("
                SELECT rty_Name, rty_OriginatingDBID, rty_IDInOriginatingDB
                  FROM defRecTypes
                 WHERE 1
            ");
            while ($row = $stmt->fetch()) {
                $key = $row['rty_Name'] . '|' . $row['rty_OriginatingDBID'] . '|' . $row['rty_IDInOriginatingDB'] . '|' . $db;
                if (isset($seen[$key])) {
                    continue;
                }
                $seen[$key] = true;
                $rows[] = [
                    $row['rty_Name'],
                    $row['rty_OriginatingDBID'],
                    $row['rty_IDInOriginatingDB'],
                    $db,
                ];
            }
        } catch (Throwable $e) {
            $res->addError("Error listing rectypes+concept IDs in $db: " . $e->getMessage());
        }
    }

    usort($rows, static function ($a, $b) {
        return strcmp(implode("\t", $a), implode("\t", $b));
    });

    try {
        writeTsv($outPath, ['rty_Name', 'rty_OriginatingDBID', 'rty_IDInOriginatingDB', 'db'], $rows);
        $res->addMessage("Wrote rectypes+concept IDs list to $outPath");
    } catch (Throwable $e) {
        $res->addError("Failed to write rectypes+concept IDs TSV: " . $e->getMessage());
    }

    $res->finish();
    return $res;
}

