function task_listAllUsersUnique(array $config): TaskResult
{
    $res = new TaskResult('list_all_users_unique');

    $resultsDir = $config['resultsDir'];
    try {
        ensureDir($resultsDir);
    } catch (Throwable $e) {
        $res->addError("Cannot ensure results directory: " . $e->getMessage());
        $res->finish();
        return $res;
    }

    $cumulativePath = $resultsDir . '/cumulative_list_of_users_unique.tsv';

    $users = [];
    if (is_file($cumulativePath)) {
        $fh = fopen($cumulativePath, 'r');
        if ($fh) {
            while (($row = fgetcsv($fh, 0, "\t")) !== false) {
                if (!isset($row[0])) {
                    continue;
                }
                $email = trim($row[0]);
                if ($email === '' || $email[0] === '#') {
                    continue;
                }
                $users[$email] = [
                    $email,
                    $row[1] ?? '',
                    $row[2] ?? '',
                ];
            }
            fclose($fh);
        }
    }

    $dbs = getHeuristDatabases($config);
    foreach ($dbs as $db) {
        try {
            $pdo = getPdo($config, $db);
            $sql = "
                SELECT ugr_eMail, ugr_FirstName, ugr_LastName
                  FROM sysUGrps
                 WHERE ugr_Type = 'user'
                   AND ugr_eMail NOT IN (
                        'guest@null',
                        'info@heuristscholar.org',
                        'info@heuristnetwork.org'
                   )
            ";
            $stmt = $pdo->query($sql);
            while ($row = $stmt->fetch()) {
                $email = trim((string)$row['ugr_eMail']);
                if ($email === '') {
                    continue;
                }
                $users[$email] = [
                    $email,
                    (string)$row['ugr_FirstName'],
                    (string)$row['ugr_LastName'],
                ];
            }
        } catch (Throwable $e) {
            $res->addError("Error listing users (unique) in $db: " . $e->getMessage());
        }
    }

    ksort($users, SORT_STRING);
    $rows = array_values($users);

    try {
        writeTsv($cumulativePath, [], $rows);
        $res->addMessage("Wrote cumulative unique users to $cumulativePath");
    } catch (Throwable $e) {
        $res->addError("Failed to write cumulative users TSV: " . $e->getMessage());
    }

    $monthPrefix = date('Y-m');
    $zipPath = sprintf('%s/%s_archive_cumulative_list_of_users_unique.zip', $resultsDir, $monthPrefix);
    if (is_file($cumulativePath)) {
        $cmd = sprintf(
            'zip -j -q %s %s',
            escapeshellarg($zipPath),
            escapeshellarg($cumulativePath)
        );
        $exit = runShellCommand($cmd, $res);
        if ($exit === 0) {
            $res->addMessage("Created monthly zip archive $zipPath");
        }
    }

    $res->finish();
    return $res;
}

function task_listAllUsersWithDbs(array $config): TaskResult
{
    $res = new TaskResult('list_all_users_with_dbs');

    $resultsDir = $config['resultsDir'];
    try {
        ensureDir($resultsDir);
    } catch (Throwable $e) {
        $res->addError("Cannot ensure results directory: " . $e->getMessage());
        $res->finish();
        return $res;
    }

    $outPath = $resultsDir . '/list_of_users_on_all_dbs.tsv';

    $dbs = getHeuristDatabases($config);
    $rows = [];

    $rows[] = [
        'Email', 'FirstName', 'LastName', 'Database',
        'LastLoginTime', 'LoginCount', 'Organisation', 'Interests',
    ];

    foreach ($dbs as $db) {
        try {
            $pdo = getPdo($config, $db);
            $sql = "
                SELECT ugr_eMail, ugr_FirstName, ugr_LastName,
                       ugr_LastLoginTime, ugr_LoginCount,
                       ugr_organisation, ugr_interests
                  FROM sysUGrps
                 WHERE ugr_Type = 'user'
                   AND ugr_eMail NOT IN (
                        'guest@null',
                        'info@heuristscholar.org',
                        'info@heuristnetwork.org'
                   )
            ";
            $stmt = $pdo->query($sql);
            while ($row = $stmt->fetch()) {
                $rows[] = [
                    $row['ugr_eMail'],
                    $row['ugr_FirstName'],
                    $row['ugr_LastName'],
                    $db,
                    $row['ugr_LastLoginTime'],
                    $row['ugr_LoginCount'],
                    $row['ugr_organisation'],
                    $row['ugr_interests'],
                ];
            }
        } catch (Throwable $e) {
            $res->addError("Error listing users with DBs in $db: " . $e->getMessage());
        }
    }

    $header = array_shift($rows);
    usort($rows, static function ($a, $b) {
        $cmp = strcmp((string)$a[0], (string)$b[0]);
        if ($cmp !== 0) {
            return $cmp;
        }
        return strcmp((string)$a[3], (string)$b[3]);
    });
    array_unshift($rows, $header);

    try {
        writeTsv($outPath, [], $rows);
        $res->addMessage("Wrote users-with-dbs list to $outPath");
    } catch (Throwable $e) {
        $res->addError("Failed to write users-with-dbs TSV: " . $e->getMessage());
    }

    $res->finish();
    return $res;
}

