// -----------------------------------------------------------------------------
// EMAIL SUMMARY
// -----------------------------------------------------------------------------

function overallStatus(array $taskResults): string
{
    $worst = 'OK';
    foreach ($taskResults as $r) {
        if ($r->status === 'ERROR') {
            return 'ERROR';
        }
        if ($r->status === 'WARNING') {
            $worst = 'WARNING';
        }
    }
    return $worst;
}

function sendSummaryEmail(array $config, array $taskResults): void
{
    $status = overallStatus($taskResults);
    $subject = sprintf(
        '%s - %s on %s',
        $status,
        $config['emailSubjectPrefix'],
        $config['serverName']
    );

    $to   = $config['emailTo'];
    $from = $config['emailFrom'];

    $bodyLines = [];
    $bodyLines[] = sprintf(
        "Nightly procedures on %s completed at %s.",
        $config['serverName'],
        date('Y-m-d H:i:s')
    );
    $bodyLines[] = '';
    $bodyLines[] = "Task summary:";
    foreach ($taskResults as $r) {
        $bodyLines[] = sprintf(
            "- %s: %s (%.1fs)",
            $r->name,
            $r->status,
            $r->durationSeconds()
        );
        foreach ($r->errors as $e) {
            $bodyLines[] = "    ERROR: " . $e;
        }
        foreach ($r->warnings as $w) {
            $bodyLines[] = "    WARNING: " . $w;
        }
    }
    $bodyLines[] = '';
    $bodyLines[] = "See attached TSV/HTML files in /srv/scripts/RESULTS for details.";
    $bodyLines[] = "This message was generated by nightly_procedures.php.";

    $textBody = implode("\r\n", $bodyLines);

    $attachments = [];
    $resultsDir = $config['resultsDir'];
    $maybeFiles = [
        $resultsDir . '/list_of_dbs.tsv',
        $resultsDir . '/list_of_users_on_all_dbs.tsv',
        $resultsDir . '/cumulative_list_of_users_unique.tsv',
        $resultsDir . '/list_of_rectypes_on_all_dbs.tsv',
        $resultsDir . '/list_of_fields_on_all_dbs.tsv',
        $resultsDir . '/list_of_websites_on_all_dbs.tsv',
        $resultsDir . '/filestore_sizes.txt',
        $resultsDir . '/required_tables_check.tsv',
    ];
    foreach ($maybeFiles as $path) {
        if (is_file($path)) {
            $attachments[] = $path;
        }
    }

    if (!$attachments) {
        $headers = "From: {$from}\r\n" .
                   "Content-Type: text/plain; charset=UTF-8\r\n";
        @mail($to, $subject, $textBody, $headers);
        return;
    }

    $boundary = '==MIXED_' . md5((string)microtime(true));

    $headers = [];
    $headers[] = "From: {$from}";
    $headers[] = "MIME-Version: 1.0";
    $headers[] = "Content-Type: multipart/mixed; boundary=\"{$boundary}\"";

    $message = '';
    $message .= "--{$boundary}\r\n";
    $message .= "Content-Type: text/plain; charset=\"UTF-8\"\r\n";
    $message .= "Content-Transfer-Encoding: 7bit\r\n\r\n";
    $message .= $textBody . "\r\n";

    foreach ($attachments as $path) {
        $filename = basename($path);
        $data = file_get_contents($path);
        if ($data === false) {
            continue;
        }
        $message .= "--{$boundary}\r\n";
        $message .= "Content-Type: text/plain; name=\"{$filename}\"\r\n";
        $message .= "Content-Transfer-Encoding: base64\r\n";
        $message .= "Content-Disposition: attachment; filename=\"{$filename}\"\r\n\r\n";
        $message .= chunk_split(base64_encode($data)) . "\r\n";
    }

    $message .= "--{$boundary}--\r\n";

    @mail($to, $subject, $message, implode("\r\n", $headers));
}

// -----------------------------------------------------------------------------
// MAIN
// -----------------------------------------------------------------------------

function main(array $config): void
{
    $start = microtime(true);

    try {
        ensureDir($config['resultsDir']);
    } catch (Throwable $e) {
        fwrite(STDERR, "Cannot ensure results directory: " . $e->getMessage() . "\n");
        exit(1);
    }

    $tasks = [
        // 1. Backups
        'task_backupAllDatabases',
        'task_archiveBzipDbs',
        'task_purgeArchive',

        // 2. Verifications
        'task_checkRequiredTables',

        // 3. Reporting
        'task_listAllDbs',
        'task_listFilestoreSizes',
        'task_listAllWebsites',
        'task_listAllHeuristServers',
        'task_listAllRectypes',
        'task_listAllRectypesWithConceptIds',
        'task_listAllFields',
        'task_listAllUsersUnique',
        'task_listAllUsersWithDbs',
    ];

    $results = [];

    foreach ($tasks as $taskFn) {
        if (!function_exists($taskFn)) {
            logLine($config, "Task function $taskFn is not defined – skipping.");
            continue;
        }
        logLine($config, "Starting task $taskFn ...");
        $res = $taskFn($config);
        $results[] = $res;
        logLine($config, sprintf(
            "Finished task %s: %s (%.1fs)",
            $res->name,
            $res->status,
            $res->durationSeconds()
        ));
    }

    $overall = overallStatus($results);
    logLine($config, sprintf(
        "Nightly procedures completed with status %s in %.1fs",
        $overall,
        microtime(true) - $start
    ));

    sendSummaryEmail($config, $results);
}

main($config);
